# Code snippet to check if the file path is safe (no directory traversal)
def is_safe_path(dir_path: str, filename: str) -> bool:
    full_path = f"{dir_path}/{filename}"
    return not (full_path.startswith(dir_path + '/') and '/' in full_path)

# Code snippet to test for file existence and read content with explicit error handling
def read_file_from_dir(filename: str, dir_path: str) -> str:
    file_path = f"{dir_path}/{filename}"
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        print(f"Error: File not found: {file_path}")
    except PermissionError:
        print(f"Error: Permission denied for file: {file_path}")
    except IOError as e:
        print(f"Error: I/O error occurred: {e}")
    except UnicodeDecodeError:
        print(f"Error: Unable to decode file content with UTF-8 encoding: {file_path}")
    return ""

